// Layout controls remain available even if 3D cannot initialise.
const compactStudio=matchMedia('(max-width: 900px), (orientation: portrait)');
function setPanelOpen(open){$('#sidebar').classList.toggle('open',open);$('#studio-screen').classList.toggle('panel-collapsed',!open);$('#open-panel').setAttribute('aria-expanded',String(open));$('#open-panel').textContent=open?'Hide products':'Products & finishes';$('#bottom-products').setAttribute('aria-expanded',String(open));$('#bottom-products').textContent=open?'Close products ↓':'Products & finishes ↑';$$('[data-open-decor]').forEach(b=>b.setAttribute('aria-expanded',String(open&&!$('[data-pane=decor]').hidden)));if(!open&&$('#sidebar').contains(document.activeElement))($('#bottom-products').getClientRects().length?$('#bottom-products'):$('#open-panel')).focus()}
$('#open-panel').onclick=()=>setPanelOpen(!$('#sidebar').classList.contains('open'));$('#close-panel').onclick=()=>setPanelOpen(false);$('#bottom-products').onclick=()=>setPanelOpen(!$('#sidebar').classList.contains('open'));
compactStudio.addEventListener('change',()=>setPanelOpen(!compactStudio.matches));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').open)setPanelOpen(false)});
