for(const [id,key]of [['curtain-rod','rodWidth'],['curtain-drop','drop'],['curtain-metres','metres'],['curtain-opening','open'],['curtain-pattern','patternWidth']])$('#'+id).oninput=e=>{if(studioMode!=='curtains')return;state.curtainDrape={...curtainConfig(),[key]:Number(e.target.value)};refreshCurtains()};
